import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

const WorkerSplash = ({ onComplete }) => {
  const [phase, setPhase] = useState("cold"); // cold -> hit -> exit

  useEffect(() => {
    const hitTimer = setTimeout(() => setPhase("hit"), 1200);
    const exitTimer = setTimeout(() => setPhase("exit"), 3500);
    const completeTimer = setTimeout(onComplete, 4500);

    return () => { 
      clearTimeout(hitTimer); 
      clearTimeout(exitTimer); 
      clearTimeout(completeTimer); 
    };
  }, [onComplete]);

  return (
    <div className={`h-screen w-full flex items-center justify-center relative overflow-hidden transition-all duration-700 ${phase === 'cold' ? 'bg-[#003366]' : 'bg-[#FFF24D]'}`}>

      {/* 1. THE LENIN BLUE ATMOSPHERE (Only visible in 'cold' phase) */}
      {phase === "cold" && (
        <motion.div 
          animate={{ scale: [1, 1.1, 1], opacity: [0.3, 0.5, 0.3] }}
          transition={{ duration: 2, repeat: Infinity }}
          className="absolute w-[600px] h-[600px] bg-[#FFF24D] rounded-full blur-[120px] opacity-20"
        />
      )}

      {/* 2. THE CORE UNIT */}
      <div className={phase === "exit" ? "animate-exit" : phase === "hit" ? "animate-impact" : ""}>
        <div className="flex flex-col items-center">

          <div className="relative flex items-center">
            {/* THE T2T LOGO - BEET RED */}
            <motion.h1 
              initial={{ scale: 0.8, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              transition={{ duration: 1.2, ease: [0.16, 1, 0.3, 1] }}
              className="text-[14rem] md:text-[22rem] font-[1000] italic text-[#AB1717] tracking-tighter leading-none select-none drop-shadow-[10px_10px_0px_#003366]"
            >
              T2T
            </motion.h1>
          </div>

          {/* THE WORKER TAG - GRASSY GREEN */}
          <motion.div 
            initial={{ opacity: 0, y: 50 }}
            animate={phase === "hit" ? { opacity: 1, y: 0 } : {}}
            transition={{ duration: 0.8, ease: "easeOut" }}
            className="mt-[-40px] md:mt-[-60px] bg-[#47510B] px-12 py-3 transform skew-x-[-15deg] shadow-[8px_8px_0px_#AB1717]"
          >
            <span className="text-[#FFF24D] font-[1000] text-3xl md:text-5xl uppercase italic tracking-widest">
              Worker
            </span>
          </motion.div>
        </div>
      </div>

      {/* 3. THE "MAGIC" PERCENTAGE (Bottom Right) */}
      <div className="absolute bottom-12 right-12 overflow-hidden">
        <motion.p 
          initial={{ y: 50 }}
          animate={{ y: 0 }}
          className={`text-[6rem] font-black italic ${phase === 'cold' ? 'text-[#FFF24D]' : 'text-[#003366]'} opacity-10`}
        >
          {phase === "cold" ? "00" : "100"}
        </motion.p>
      </div>

      {/* 4. THE "PRO" INDICATOR (Top Left) */}
      <div className="absolute top-12 left-12 flex flex-col gap-1">
        <div className={`h-1 w-12 ${phase === 'cold' ? 'bg-[#FFF24D]' : 'bg-[#AB1717]'}`} />
        <span className={`font-mono text-[10px] font-bold ${phase === 'cold' ? 'text-[#FFF24D]' : 'text-[#47510B]'}`}>
          SYSTEM_V4.0_READY
        </span>
      </div>
    </div>
  );
};

export default WorkerSplash;
